}
const colFor = (book, info, pos = book.pos) => Math.max(0, Math.min(info.count - 1, Math.floor((pos.f || 0) * info.count + 1e-6)));
const spreadOf = (book, info, L, pos = book.pos) => Math.floor(colFor(book, info, pos) / L.n);
