  const offset = info.scroll ? null : pageOffset(book, s, p, L);
  let folios = '';
  if (offset != null) for (let i = 0; i < L.n; i += 1) if (lo + i < info.count) folios += `<div class="bk-folio bk-folio-${i}">${offset + lo + i + 1}</div>`;
