      items: marks.map((mark) => ({ id: `b:${mark.id}`, icon: ICON('bookmark-fill'), tint: true, title: mark.label, subtitle: `${progressOf({ ...book, finished: false, opened: 1 }, mark)}% · ${dates.format(mark.at)}` })),
